        <view class="tasks-header">
          <text class="tasks-title">最近任务</text>
          <text class="tasks-more" @click="navigateTo('plan')">全部</text>
        </view>
        <view class="task-list">
          <view class="task-card" v-for="(task, index) in recentOrders" :key="index" @click="navigateTo('plan')">
            <view class="task-info">
              <text class="task-name">{{ task.product }}</text>
              <view class="task-badge" :class="task.status">{{ task.statusText }}</view>
            </view>
            <view class="task-meta">
              <text class="task-id">任务#{{ task.id }}</text>
